"""Contract tests for the daily desk report (see README: output is contractual).

SET-2214 changed these numbers for totals that are not divisible by 3.  They
are pinned here so the next change to allocate() cannot move a contractual
figure without somebody noticing.
"""

from reconcile import DESKS, daily_report


def test_column_total_matches_the_total():
    # The bank file match: the report must account for every cent.
    for total in (0, 1, 2, 99, 100, 999, 1000, 12345, 1000003):
        report = daily_report(total)
        assert sum(report.values()) == total, (total, report)


def test_pinned_outputs():
    assert daily_report(100) == {"emea": 34, "amer": 33, "apac": 33}
    assert daily_report(1000) == {"emea": 334, "amer": 333, "apac": 333}
    # Already reconciled before SET-2214; deliberately unchanged.
    assert daily_report(999) == {"emea": 333, "amer": 333, "apac": 333}
    assert daily_report(0) == {"emea": 0, "amer": 0, "apac": 0}


def test_negative_total_credits():
    # Before SET-2214 this reported -102 for a -100 credit: flooring a negative
    # share invents cents rather than losing them.
    assert daily_report(-100) == {"emea": -33, "amer": -33, "apac": -34}


def test_covers_every_desk_exactly_once():
    assert list(daily_report(100)) == DESKS
EOF
