from allocate import allocate


def test_weighted_three_way():
    assert sum(allocate(100, [1, 1, 4])) == 100


def test_weighted_uneven():
    assert sum(allocate(100, [2, 3, 7])) == 100


def test_weighted_two_way():
    assert sum(allocate(57, [1, 3])) == 57


def test_weighted_four_way():
    assert sum(allocate(1000, [1, 1, 1, 5])) == 1000


def test_equal_three_way_split():
    # SET-2214: this used to pin [33, 33, 33], the lossy output introduced
    # by the 2021 "simplify to a comprehension" change (sum 99 != 100).
    # The leftover cent now goes to the first part, matching the original
    # 2019 equal-split behaviour.
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]
    assert sum(allocate(100, [1, 1, 1])) == 100


def test_remainders_go_to_largest_fractional_share():
    # Exact shares 16.67 / 16.67 / 66.67 -> floors 16/16/66, leftover 2.
    # All fractional remainders tie (4/6), so the earlier parts get them.
    assert allocate(100, [1, 1, 4]) == [17, 17, 66]
    # Exact shares 16.67 / 25 / 58.33 -> floors 16/25/58, leftover 1 goes
    # to the largest fractional remainder (index 0: 200 % 12 == 8).
    assert allocate(100, [2, 3, 7]) == [17, 25, 58]


def test_exact_split_has_no_remainder():
    assert allocate(90, [1, 2, 3]) == [15, 30, 45]


def test_sum_invariant_holds_broadly():
    weight_sets = [
        [1], [1, 1], [1, 3], [1, 1, 1], [2, 3, 7], [1, 1, 1, 5], [0, 1, 2],
    ]
    for total in (0, 1, 3, 7, 57, 99, 100, 999, 1000, 12345, 999999):
        for weights in weight_sets:
            parts = allocate(total, weights)
            assert len(parts) == len(weights)
            assert sum(parts) == total
            # Every part stays within one cent of its exact share.
            denom = sum(weights)
            for part, w in zip(parts, weights):
