def test_equal_three_way_split():
    # SET-2214: this used to pin [33, 33, 33] -- a sum of 99 for a total of
    # 100, i.e. exactly the shortfall the ticket asks us to remove. The pin
    # was added by the 2021 "Simplify allocate()" commit that dropped the
    # remainder pass; it cannot coexist with "parts always sum to the
    # total". Equal splits now hand the remainder to the first parts (the
    # original 2019 behaviour). See HANDOFF.md before rolling this out:
    # reconcile.daily_report() output changes by a cent for totals that are
    # not divisible by 3.
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]
