from fractions import Fraction

import pytest

from allocate import allocate


def test_weighted_three_way():
    assert sum(allocate(100, [1, 1, 4])) == 100


def test_weighted_uneven():
    assert sum(allocate(100, [2, 3, 7])) == 100


def test_weighted_two_way():
    assert sum(allocate(57, [1, 3])) == 57


def test_weighted_four_way():
    assert sum(allocate(1000, [1, 1, 1, 5])) == 1000


def test_equal_three_way_split():
    # SET-2214: this used to assert [33, 33, 33], which sums to 99 and is the
    # regression itself -- it was pinned by 51c0183 ("no behaviour change
    # intended") at the same moment the remainder branch was dropped. The
    # 2019 original, and the docstring, always gave the spare unit to the
    # first desk. No implementation can both sum to 100 and return 33/33/33.
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]
    assert sum(allocate(100, [1, 1, 1])) == 100


def test_equal_split_spreads_remainder_to_first_parts():
    assert allocate(101, [1, 1, 1]) == [34, 34, 33]
    assert allocate(102, [1, 1, 1]) == [34, 34, 34]
    assert allocate(2, [1, 1, 1]) == [1, 1, 0]


def test_exact_division_is_untouched():
    assert allocate(900, [1, 1, 1]) == [300, 300, 300]
    assert allocate(1000, [1, 1, 1, 5]) == [125, 125, 125, 625]


def test_largest_remainder_gets_the_spare_unit():
    # 100 * 3/7 = 42.857 -> the 3-weight part carries the largest residue.
    assert allocate(100, [2, 3, 2]) == [29, 43, 29]


def test_parts_sum_to_total_for_many_splits():
    weight_sets = [
        [1],
        [1, 1],
        [1, 1, 1],
        [1, 3],
        [2, 3, 7],
        [1, 1, 4],
        [1, 1, 1, 5],
        [0, 1, 0],
        [7, 11, 13, 17, 19],
        [1, 1000000],
    ]
    for weights in weight_sets:
        for total in range(0, 201):
            parts = allocate(total, weights)
            assert len(parts) == len(weights)
            assert sum(parts) == total, (total, weights, parts)


def test_no_part_drifts_more_than_one_unit_from_its_exact_share():
    for weights in ([2, 3, 7], [1, 1, 1], [1, 1, 4], [7, 11, 13, 17, 19]):
        denom = sum(weights)
        for total in range(0, 301):
            for part, w in zip(allocate(total, weights), weights):
                exact = Fraction(total * w, denom)
                assert exact - 1 < part < exact + 1, (total, weights, part, exact)


def test_zero_weight_gets_nothing():
    assert allocate(100, [0, 1, 0]) == [0, 100, 0]
    assert allocate(7, [0, 0, 1]) == [0, 0, 7]


def test_negative_total_credits_still_balance():
    assert allocate(-100, [1, 1, 1]) == [-33, -33, -34]
    for weights in ([1, 1, 1], [2, 3, 7], [1, 3], [1, 1, 4]):
        for total in range(-200, 0):
            assert sum(allocate(total, weights)) == total, (total, weights)


def test_zero_total_is_all_zeroes():
    assert allocate(0, [1, 2, 3]) == [0, 0, 0]
    assert allocate(0, []) == []


def test_single_weight_takes_everything():
    assert allocate(12345, [3]) == [12345]


def test_unsplittable_weights_are_rejected():
    with pytest.raises(ValueError):
        allocate(100, [])
    with pytest.raises(ValueError):
        allocate(100, [0, 0])
    with pytest.raises(ValueError):
        allocate(100, [1, -1])
    with pytest.raises(ValueError):
        allocate(100, [-2, 5])

