        weights[random.randrange(n)] = 1
    denom = sum(weights)
    for w, got in zip(weights, allocate(total, weights)):
        exact = Fraction(total * w, denom)
        if not (exact - 1 < got <= exact or exact <= got < exact + 1):
            print("PROP FAIL", total, weights); fails += 1; break
        if abs(Fraction(got) - exact) >= 1:
            print("DRIFT FAIL", total, weights, got, float(exact)); fails += 1; break

# 3. Determinism + zero-weight parts get nothing.
for _ in range(20000):
    n = random.randint(1, 6)
    total = random.randint(0, 10**5)
    weights = [random.randint(0, 20) for _ in range(n)]
    if sum(weights) == 0:
        continue
    a, b = allocate(total, weights), allocate(total, weights)
    if a != b:
        print("DETERMINISM FAIL", total, weights); fails += 1; break
    for w, got in zip(weights, a):
        if w == 0 and got != 0:
            print("ZERO-WEIGHT FAIL", total, weights, a); fails += 1; break

# 4. Bad input is loud, not silently wrong.
for bad in ([], [0, 0, 0], [1, -2, 3]):
    try:
        allocate(100, bad); print("NO RAISE for", bad); fails += 1
    except ValueError:
        pass

