    # with the SET-2214 invariant, so it now pins the restored 2019 output:
    # the leftover cent goes to the first part.
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]
    assert sum(allocate(100, [1, 1, 1])) == 100


# --- invariant and fairness properties -------------------------------------


def test_remainder_goes_to_largest_fractional_share():
    # Exact shares: 100*1/3=33.33, 100*2/3=66.67 -> floors 33/66, one unit
    # left, and 2/3 has the larger remainder so it takes it.
    assert allocate(100, [1, 2]) == [33, 67]


def test_exact_division_is_untouched():
    assert allocate(1000, [1, 1, 1, 5]) == [125, 125, 125, 625]
    assert allocate(90, [1, 2]) == [30, 60]


def test_zero_weight_gets_nothing():
    assert allocate(100, [0, 1]) == [0, 100]
    assert allocate(100, [0, 0, 1]) == [0, 0, 100]


def test_zero_total():
    assert allocate(0, [1, 2, 3]) == [0, 0, 0]


def test_single_weight_gets_everything():
    assert allocate(12345, [7]) == [12345]


def test_negative_total_still_sums_exactly():
    # Reversals/refunds flow through the ledger as negative cents.
    assert allocate(-100, [1, 1, 1]) == [-33, -33, -34]
    assert sum(allocate(-100, [1, 1, 1])) == -100
    assert sum(allocate(-57, [1, 3])) == -57
    assert sum(allocate(-1, [1, 1, 1])) == -1


@pytest.mark.parametrize("total", list(range(0, 60)) + [-1, -7, -100, -1001])
@pytest.mark.parametrize(
    "weights",
    [[1, 1], [1, 1, 1], [1, 1, 4], [2, 3, 7], [1, 1, 1, 5], [0, 1], [5, 0, 3], [1]],
)
def test_parts_always_sum_to_total(total, weights):
    parts = allocate(total, weights)
    assert sum(parts) == total
    assert len(parts) == len(weights)


@pytest.mark.parametrize("total", list(range(0, 40)) + [-1, -37])
@pytest.mark.parametrize("weights", [[1, 1, 1], [2, 3, 7], [1, 1, 4], [1, 5]])
def test_each_part_within_one_unit_of_exact_share(total, weights):
    denom = sum(weights)
    for part, w in zip(allocate(total, weights), weights):
        exact = Fraction(total * w, denom)
        assert abs(Fraction(part) - exact) < 1


# --- input validation ------------------------------------------------------


def test_negative_weight_rejected():
    with pytest.raises(ValueError):
        allocate(100, [1, -1])


def test_zero_denominator_rejected():
    with pytest.raises(ValueError):
        allocate(100, [0, 0])


def test_empty_weights_with_nonzero_total_rejected():
    # No part can absorb the total, so the invariant would be unsatisfiable.
    with pytest.raises(ValueError):
        allocate(100, [])


def test_empty_weights_with_zero_total():
    assert allocate(0, []) == []


def test_non_integer_inputs_rejected():
    with pytest.raises(TypeError):
        allocate(100.0, [1, 1])
    with pytest.raises(TypeError):
        allocate(100, [1, 1.5])

